```python
import calendar
from datetime import datetime, date, timedelta

_WEEKDAY_MAP = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def _parse_dt(s: str) -> datetime:
    if s.endswith("Z"):
        s = s[:-1]
    return datetime(
        int(s[0:4]),
        int(s[5:7]),
        int(s[8:10]),
        int(s[11:13]),
        int(s[14:16]),
    )


def _format_utc(dt: datetime) -> str:
    return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}T{dt.hour:02d}:{dt.minute:02d}Z"


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    freq = rule.get("freq")
    if freq not in ("daily", "weekly", "monthly", "yearly"):
        raise ValueError("unknown freq")

    interval = rule.get("interval", 1)
    if not isinstance(interval, int) or interval < 1:
        raise ValueError("interval must be >= 1")

    if "count" in rule and "until" in rule:
        raise ValueError("cannot specify both count and until")

    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError("cannot specify both by_month_day and by_nth_weekday")

    start_dt = _parse_dt(rule["start"])
    offset_delta = timedelta(minutes=rule.get("utc_offset_minutes", 0))

    ws = _parse_dt(window_start)
    we = _parse_dt(window_end)

    local_start = ws + offset_delta
    local_end = we + offset_delta

    if local_start >= local_end:
        return []

    has_count = "count" in rule
    count = rule.get("count") if has_count else None
    if has_count and (count is None or count <= 0):
        return []

    if has_count:
        lower_dt = start_dt
        end_dt = local_end
        if lower_dt >= end_dt:
            return []
    else:
        lower_dt = local_start if local_start > start_dt else start_dt
        end_dt = local_end

        if "until" in rule:
            until_dt = _parse_dt(rule["until"])
            if until_dt < start_dt:
                return []
            until_exclusive = until_dt + timedelta(minutes=1)
            if until_exclusive < end_dt:
                end_dt = until_exclusive

        if lower_dt >= end_dt:
            return []

    exclude = {_parse_dt(x) for x in (rule.get("exclude") or [])}

    start_date = start_dt.date()
    start_time = start_dt.time()
    start_year = start_date.year
    start_month = start_date.month
    start_day = start_date.day
    start_month_idx = start_year * 12 + start_month - 1

    if freq == "daily":
        def gen(lower: datetime, end: datetime):
            if lower >= end or start_dt >= end:
                return

            max_offset = (end.date() - start_date).days
            if max_offset < 0:
                return

            if lower <= start_dt:
                offset = 0
            else:
                delta = (lower.date() - start_date).days
                if delta < 0:
                    delta = 0
                if delta > max_offset:
                    return

                q, r = divmod(delta, interval)
                k = q + (1 if r else 0)
                if k > max_offset // interval:
                    return
                offset = k * interval

            try:
                occ = start_dt + timedelta(days=offset)
            except OverflowError:
                return

            if occ < lower:
                if offset > max_offset - interval:
                    return
                offset += interval
                try:
                    occ = start_dt + timedelta(days=offset)
                except OverflowError:
                    return

            while offset <= max_offset:
                if occ >= end:
                    return
                yield occ

                if offset > max_offset - interval:
                    return
                offset += interval
                try:
                    occ = start_dt + timedelta(days=offset)
                except OverflowError:
                    return

    elif freq == "weekly":
        raw_by_weekday = rule.get("by_weekday")
        if raw_by_weekday is None:
            allowed_weekdays = [start_date.weekday()]
        else:
            allowed_weekdays = sorted({_WEEKDAY_MAP[w] for w in raw_by_weekday})

        start_monday = start_date - timedelta(days=start_date.weekday())

        def first_weekly(target_day: date, end_day: date):
            if target_day < start_date:
                target_day = start_date
            if target_day > end_day:
                return None

            monday = target_day - timedelta(days=target_day.weekday())
            week_idx = ((monday - start_monday).days) // 7
            if week_idx < 0:
                week_idx = 0

            max_week_idx = ((end_day - start_monday).days) // 7
            if max_week_idx < week_idx:
                return None

            mod = week_idx % interval
            if mod != 0:
                add = interval - mod
                if week_idx > max_week_idx - add:
                    return None
                week_idx += add

            while week_idx <= max_week_idx:
                try:
                    week_monday = start_monday + timedelta(weeks=week_idx)
                except OverflowError:
                    return None

                for wd in allowed_weekdays:
                    candidate = week_monday + timedelta(days=wd)
                    if candidate < start_date:
                        continue
                    if candidate >= target_day:
                        if candidate <= end_day:
                            return candidate
                        return None

                if week_idx > max_week_idx - interval:
                    return None
                week_idx += interval

            return None

        def gen(lower: datetime, end: datetime):
            if lower >= end:
                return

            end_day = end.date()
            target = lower.date()

            while True:
                d = first_weekly(target, end_day)
                if d is None:
                    return

                occ = datetime.combine(d, start_time)
                if occ < lower:
                    target = d + timedelta(days=1)
                    continue

                if occ >= end:
                    return

                yield occ
                target = d + timedelta(days=1)

    elif freq == "monthly":
        by_month_day = rule.get("by_month_day") if "by_month_day" in rule else None
        by_nth_raw = rule.get("by_nth_weekday") if "by_nth_weekday" in rule else None

        nth_n = None
        nth_wd = None
        if by_nth_raw is not None:
            nth_n, wd = by_nth_raw
            nth_wd = _WEEKDAY_MAP[wd]

        def month_occurrence_dates(y: int, m: int):
            dim = calendar.monthrange(y, m)[1]

            if by_month_day is not None:
                days = set()
                for md in by_month_day:
                    if md > 0:
                        if md <= dim:
                            days.add(md)
                    else:
                        day = dim + md + 1
                        if 1 <= day <= dim:
                            days.add(day)
                return [date(y, m, d) for d in sorted(days)]

            if by_nth_raw is not None:
                if nth_n > 0:
                    first_wd = date(y, m, 1).weekday()
                    day = 1 + ((nth_wd - first_wd) % 7) + (nth_n - 1) * 7
                    if day <= dim:
                        return [date(y, m, day)]
                    return []

                last_wd = date(y, m, dim).weekday()
                day = dim - ((last_wd - nth_wd) % 7) + (nth_n + 1) * 7
                if 1 <= day <= dim:
                    return [date(y, m, day)]
                return []

            if start_day <= dim:
                return [date(y, m, start_day)]
            return []

        def first_monthly(target_day: date, end_day: date):
            if target_day < start_date:
                target_day = start_date
            if target_day > end_day:
                return None

            target_month_idx = target_day.year * 12 + target_day.month - 1
            if target_month_idx < start_month_idx:
                target_month_idx = start_month_idx

            end_month_idx = end_day.year * 12 + end_day.month - 1
            if target_month_idx > end_month_idx:
                return None

            delta = target_month_idx - start_month_idx
            mod = delta % interval
            if mod != 0:
                add = interval - mod
                if target_month_idx > end_month_idx - add:
                    return None
                target_month_idx += add

            while target_month_idx <= end_month_idx:
                y, m = divmod(target_month_idx, 12)
                m += 1

                for d in month_occurrence_dates(y, m):
                    if d < start_date:
                        continue
                    if d >= target_day:
                        if d <= end_day:
                            return d
                        return None

                if target_month_idx > end_month_idx - interval:
                    return None
                target_month_idx += interval

            return None

        def gen(lower: datetime, end: datetime):
            if lower >= end:
                return

            end_day = end.date()
            target = lower.date()

            while True:
                d = first_monthly(target, end_day)
                if d is None:
                    return

                occ = datetime.combine(d, start_time)
                if occ < lower:
                    target = d + timedelta(days=1)
                    continue

                if occ >= end:
                    return

                yield occ
                target = d + timedelta(days=1)

    else:  # yearly
        def first_yearly(target_day: date, end_day: date):
            if target_day < start_date:
                target_day = start_date
            if target_day > end_day:
                return None

            year = target_day.year
            if year < start_year:
                year = start_year

            end_year = end_day.year
            if year > end_year:
                return None

            delta = year - start_year
            mod = delta % interval
            if mod != 0:
                add = interval - mod
                if year > end_year - add:
                    return None
                year += add

            while year <= end_year:
                try:
                    d = date(year, start_month, start_day)
                except ValueError:
                    if year > end_year - interval:
                        return None
                    year += interval
                    continue

                if d >= target_day:
                    if d <= end_day:
                        return d
                    return None

                if year > end_year - interval:
                    return None
                year += interval

            return None

        def gen(lower: datetime, end: datetime):
            if lower >= end:
                return

            end_day = end.date()
            target = lower.date()

            while True:
                d = first_yearly(target, end_day)
                if d is None:
                    return

                occ = datetime.combine(d, start_time)
                if occ < lower:
                    target = d + timedelta(days=1)
                    continue

                if occ >= end:
                    return

                yield occ
                target = d + timedelta(days=1)

    result = []

    if has_count:
        generated = 0
        for occ in gen(lower_dt, end_dt):
            generated += 1
            if occ >= local_start and occ not in exclude:
                result.append(_format_utc(occ - offset_delta))
            if generated >= count:
                break
        return result

    for occ in gen(lower_dt, end_dt):
        if occ not in exclude:
            result.append(_format_utc(occ - offset_delta))

    return result
